void need(bool b,const char* s){if(!b)throw std::runtime_error(s);}
live::FileIdentity id(const YAML::Node& n){return {n["path"].as<std::string>(),n["sha256"].as<std::string>(),n["bytes"].as<live::Count>()};}
std::string readPinned(const live::FileIdentity& pin,std::size_t cap){need(pin.bytes>0&&pin.bytes<=cap,"finite pinned input byte envelope");int fd=::open(pin.path.c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW);need(fd>=0,"nofollow pinned input open");struct Close{int fd;~Close(){::close(fd);}} closer{fd};struct stat st{};need(::fstat(fd,&st)==0&&S_ISREG(st.st_mode)&&static_cast<live::Count>(st.st_size)==pin.bytes,"opened exact regular input size");std::string text(pin.bytes,'\0');std::size_t at=0;while(at<text.size()){auto n=::read(fd,text.data()+at,text.size()-at);if(n<0&&errno==EINTR)continue;need(n>0,"complete input read");at+=n;}char tail;need(::read(fd,&tail,1)==0,"input grew");unsigned char digest[32];unsigned n=0;need(EVP_Digest(text.data(),text.size(),digest,&n,EVP_sha256(),nullptr)==1&&n==32,"parsed byteSHA");std::string sha;for(unsigned char b:digest){sha.push_back("0123456789abcdef"[b>>4]);sha.push_back("0123456789abcdef"[b&15]);}need(sha==pin.sha256,"opened parsed input exactSHA");return text;}
Eigen::VectorXd q7(const YAML::Node& n){need(n.IsSequence()&&n.size()==7,"raw nominal q7");Eigen::VectorXd q(7);for(int i=0;i<7;++i)q(i)=n[i].as<double>();need(q.allFinite(),"raw nominal finite q rad");return q;}
struct Output {std::uint64_t used=0;std::filesystem::path root;Output(const std::string& dir):root(dir){need(root.is_absolute()&&!std::filesystem::exists(root)&&std::filesystem::create_directory(root),"fresh absolute geometry evidence directory");}void emit(int fd,const std::string& bytes){need(used<=33554432&&bytes.size()<=33554432-used,"global provider evidence32MiB beforewrite");used+=bytes.size();std::size_t at=0;while(at<bytes.size()){auto n=::write(fd,bytes.data()+at,bytes.size()-at);if(n<0&&errno==EINTR)continue;need(n>0,"provider evidence prefix write");at+=n;}}int open(const std::string& n){int fd=::open((root/n).c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW|O_CLOEXEC,0600);need(fd>=0,"fresh output file");return fd;}void write(const std::string& name,const std::string& data){int fd=open(name);try{emit(fd,data);need(::fsync(fd)==0,"output fsync");::close(fd);}catch(...){::close(fd);throw;}}};
struct Sink {Output& out;int fd;Sink(Output& o,const std::string& n):out(o),fd(o.open(n)){}~Sink(){::close(fd);}void line(const std::string& s){out.emit(fd,s);}void flush(){need(::fsync(fd)==0,"retained geometry output fsync");}};
std::string ident(const geo::Query& q){return phase5_nominal_geometry_selection_v1::identity(q);}
void roster(const geo::Snapshot& s,std::size_t expected){need(s.queries.size()==expected&&expected>0,"complete original true+cover query roster");for(const auto& q:s.queries)need(q.gradient.size()==7&&q.gradient.allFinite()&&std::isfinite(q.distance)&&q.normal.allFinite()&&q.witness_a.allFinite()&&q.witness_b.allFinite()&&std::abs(q.normal.norm()-1)<=1e-6&&(q.witness_b-q.witness_a-q.distance*q.normal).norm()<=1e-6,"original finite gradients/world witnesses/unit normals");}
std::string counters(const Counts& c){std::ostringstream o;o<<"scene_attempts="<<c.scene_attempts<<",scene_returns="<<c.scene_returns<<",primitive_attempts="<<c.primitive_attempts<<",true_attempts="<<c.true_attempts<<",true_returns="<<c.true_returns<<",cover_attempts="<<c.cover_attempts<<",cover_returns="<<c.cover_returns<<",FK_attempts="<<c.fk_attempts<<",FK_returns="<<c.fk_returns<<",analytic_J_attempts="<<c.jac_attempts<<",analytic_J_returns="<<c.jac_returns;return o.str();}
void pin(const live::FileIdentity& x){auto a=live::observePinnedFile(x.path,x.sha256);need(a.bytes==x.bytes,"SDK/config byte identity");}
std::vector<std::string> loaded(){std::vector<std::string> out;dl_iterate_phdr([](dl_phdr_info* info,std::size_t,void* ptr){auto& paths=*static_cast<std::vector<std::string>*>(ptr);if(info->dlpi_name&&*info->dlpi_name&&std::string(info->dlpi_name).find("linux-vdso")==std::string::npos)paths.push_back(std::filesystem::canonical(info->dlpi_name).string());return 0;},&out);std::sort(out.begin(),out.end());return out;}
void libraryPins(const YAML::Node& profile,const std::vector<std::string>& actual){for(const auto& path:actual){bool found=false;for(const auto& n:profile["loaded_libraries"]){auto x=id(n);if(std::filesystem::canonical(x.path).string()==path){pin(x);found=true;break;}}need(found,"actual loaded SDK library not bound by profile");}}
